(window.LADDER_CARDS=window.LADDER_CARDS||{})["1·phys"]=[{"q":"When is the bulb lit?","a":"when there is an unbroken path from the battery, through the bulb, and back","w":["whenever the battery is fresh","when any button is held down","when the wire is cut once"],"why":"A given from observation (1a5)."},
 {"q":"On this page, what stands for a letter, and what for the answer?","a":"a button held down for the letter; the bulb, lit 1 and dark 0, for the answer","w":["the battery for the letter; the wire for the answer","the bulb for the letter; the button for the answer","a cut wire for the letter; the battery for the answer"],"why":"The two agreements, made the way 1e1 agreed on its marks."},
 {"q":"Two buttons in a line. What column does the bulb show?","a":"1 0 0 0, the column of P ∧ Q","w":["1 1 1 0, the column of P ∨ Q","1 0 0 1, the column of P ⇔ Q","0 1 1 0, the column of P ⊕ Q"],"why":"The path is unbroken only when both gaps are closed."},
 {"q":"Two buttons side by side. What column does the bulb show?","a":"1 1 1 0, the column of P ∨ Q","w":["1 0 0 0, the column of P ∧ Q","0 1 1 0, the column of P ⊕ Q","0 0 0 1, the column of neither"],"why":"There are two ways through, and the or is the generous or of 1c5."},
 {"q":"A button that breaks the wire is on the path. What does the bulb show?","a":"¬P: T gives 0, F gives 1","w":["P: T gives 1, F gives 0","⊤: lit in every row","⊥: dark in every row"],"why":"Holding it down opens the gap: the not machine of 1e2."},
 {"q":"Which wirings give the three machines 1e16 used to reach every column?","a":"a line for and, side by side for or, the breaking button for not","w":["a line for or, side by side for and, the breaking button for not","two levers for and, a line for or, a bare wire for not","side by side for not, a line for and, a lever for or"],"why":"Each of the three machines has a wiring."},
 {"q":"Why can an and not work a stairway light?","a":"from the row FF, changing P alone gives the row TF, and that still gives 0","w":["an and has no row FF","an and lights in every row","an and needs three buttons"],"why":"A stairway light must change whenever one letter changes."},
 {"q":"Two lever switches, straight wires. What column does the bulb show?","a":"1 0 0 1, the column of P ⇔ Q","w":["0 1 1 0, the column of P ⊕ Q","1 0 0 0, the column of P ∧ Q","1 1 1 0, the column of P ∨ Q"],"why":"The path is unbroken exactly when both levers sit on the same wire."},
 {"q":"The middle wires of the stairway are crossed. What column does the bulb show?","a":"0 1 1 0, the column of P ⊕ Q","w":["1 0 0 1, the column of P ⇔ Q","0 0 0 0, the column of ⊥","1 1 0 1, the column of Q ⇒ P"],"why":"The path is unbroken exactly when the levers differ."},
 {"q":"Wiring one is P ∧ (Q ∨ R) and wiring two is (P ∧ Q) ∨ (P ∧ R). How do their columns compare?","a":"they match in all eight rows","w":["they differ in the row TFF","they differ in every row where P is F","they match in four rows only"],"why":"A bulb shows a column, and cannot show how the column was wired (1e14)."},
 {"q":"Which of the two wirings would someone who pays for the parts build?","a":"wiring one: three gaps to close, against four","w":["wiring two: it shows more","either: they cost the same","neither: a bulb cannot show an and of an or"],"why":"Same column, fewer parts; wiring two needs two contacts under one finger."},
 {"q":"A bare wire is put side by side with button p. What does the bulb show?","a":"⊤: P ∨ ⊤ is lit in every row","w":["P: the button still decides","¬P: the bare wire reverses the button","⊥: the bulb goes dark"],"why":"There is now always a way through (1f2)."},
 {"u":"1·phys.1.1","q":"What stands for a letter on this page, what stands for the answer, and what is one row?","a":"a button held down for a letter, the bulb for the answer, and one way of holding the buttons is one row","w":["the battery for a letter, the wire for the answer, and one bulb is one row","the bulb for a letter, a button for the answer, and one wire is one row","a cut for a letter, the battery for the answer, and one press is one row"],"why":"The wiring fills in its own table (1e6)."},
 {"u":"1·phys.2.1","q":"Why are two buttons in a line an and? Point to the row where the bulb is lit.","a":"the path has two gaps and is unbroken only when both are closed: the bulb is lit in the row TT only","w":["either gap closed is enough: lit in TT, TF and FT","the bulb is lit when the buttons differ: rows TF and FT","the bulb is lit when neither is held: row FF"],"why":"The column 1 0 0 0 is the column of P ∧ Q (1e2)."},
 {"u":"1·phys.3.1","q":"Why are two buttons side by side an or, and which or is it?","a":"there are two ways through, so either button closes the path, and with both held the bulb is lit too: the generous or","w":["both buttons must be held, so it is an and","with both held the path breaks, so it is or but not both","only the top branch counts, so it is P alone"],"why":"1 1 1 0, the column of P ∨ Q (1c5)."},
 {"u":"1·phys.4.1","q":"What does a button that breaks the wire do, and which machine of 1e2 does its bulb show?","a":"it is closed while untouched and holding it opens the gap, so the bulb shows the not machine, ¬P","w":["it closes when held, so the bulb shows P","it cuts the wire for good, so the bulb shows ⊥","it joins two wires, so the bulb shows P ⇔ Q"],"why":"T gives 0 and F gives 1, as the refrigerator light shows."},
 {"u":"1·phys.5.1","q":"Why can two buttons in a line not work a stairway light? Point to the rows.","a":"from the row FF, changing P alone gives TF, and the and gives 0 in both, so the light has not changed","w":["from TT, changing P gives FT, and both give 1","the and has no row where both letters are F","the and gives 1 in every row, so nothing ever changes"],"why":"A stairway needs the answer to change whenever one letter changes."},
 {"u":"1·phys.6.1","q":"Why can someone who looks only at the bulb never tell wiring one from wiring two?","a":"the two wirings have the same column in all eight rows, and a bulb shows only the column","w":["the bulb is too dim to show a difference","the two wirings differ in the row TFF, but nobody tries it","wiring two has no bulb"],"why":"Same column, same statement by the table's lights (1e14)."},
 {"u":"1·phys.7.1","q":"Why is “The buttons are side by side and the bulb is lit, so p is held down” a move to watch out for?","a":"an or does not hand over a part: the bulb is lit in the row FT too, where p is up","w":["side by side is an and, so p must be up","a lit bulb always means every button is held","the bulb cannot be lit with buttons side by side"],"why":"Outside the collect: with ¬Q also in hand, the remaining option would give P (1c9)."}];
