(window.LADDER_CARDS=window.LADDER_CARDS||{})["17·phys2"]=[{"q": "Δv = u ln(m₀/m₁). What is the equation called?", "a": "the Tsiolkovsky rocket equation", "w": ["the vis-viva equation", "Kepler’s third law", "the ideal gas law"], "why": "Tsiolkovsky, 1903."}, {"q": "In the rocket equation, what is m₀/m₁?", "a": "the mass ratio: full mass over empty mass", "w": ["the thrust over the weight", "the exhaust speed over the final speed", "the fuel mass over the payload"], "why": "Δv grows as its logarithm."}, {"q": "Exhaust speed u divided by g, in seconds. What is it called?", "a": "specific impulse", "w": ["thrust", "burn time", "delta-v"], "why": "A measure of engine efficiency."}, {"q": "Exhaust speed 3 km/s, mass ratio e². What Δv does the burn give?", "a": "6 km/s", "w": ["3 km/s", "9 km/s", "e² km/s"], "why": "3 · ln e² = 6."}, {"q": "Exhaust speed 4 km/s. What mass ratio gives Δv = 8 km/s?", "a": "e² ≈ 7.4", "w": ["2", "4", "e⁸"], "why": "m₀/m₁ = e^(Δv/u)."}, {"q": "Doubling the Δv asked for, at the same exhaust speed. What happens to the mass ratio?", "a": "it is squared", "w": ["it doubles", "it quadruples", "it rises by 2"], "why": "e^(2Δv/u) = (e^(Δv/u))²."}, {"q": "Why does a log appear in the rocket equation?", "a": "each bit of exhaust adds u times its share of the current mass, and adding those is the area under 1/m", "w": ["the engine burns logarithmically", "thrust falls off logarithmically", "gravity weakens with height"], "why": "∫dm/m = ln m."}, {"q": "Dropping empty tanks during ascent. What is it called?", "a": "staging", "w": ["throttling", "gimbaling", "aerobraking"], "why": "Each stage’s Δv adds, so the mass ratios multiply."}, {"q": "Two stages with mass ratios 3 and 4, same exhaust speed u. What is the total Δv?", "a": "u ln 12", "w": ["u ln 7", "7u", "12u"], "why": "Logs add: ln 3 + ln 4."}, {"q": "Why are ion engines used for deep-space probes but not for launch?", "a": "very high exhaust speed, but a tiny thrust", "w": ["low exhaust speed, huge thrust", "they need air to work", "they are heavier than chemical engines"], "why": "Months to build speed; far less propellant."}];
