(window.LADDER_CARDS=window.LADDER_CARDS||{})["18·phys2"]=[{"q": "Which radiation is stopped by a sheet of paper or the outer skin?", "a": "alpha", "w": ["beta", "gamma", "X-rays"], "why": "Heavy and doubly charged, it loses energy fast."}, {"q": "Which radiation is stopped by a few millimetres of aluminium?", "a": "beta", "w": ["alpha only", "gamma", "neutrons"], "why": "Fast electrons have a range."}, {"q": "Why are gamma rays thinned but never fully stopped?", "a": "each photon passes untouched until, by chance, it interacts, so a fixed share passes each thickness", "w": ["they lose energy steadily and have a range", "they are too fast to stop", "they are charged and repelled"], "why": "Exponential attenuation."}, {"q": "The thickness that halves a gamma beam. What is it called?", "a": "the half-value layer", "w": ["the range", "the mean free path squared", "the attenuation length cubed"], "why": "μ = ln 2 / HVL."}, {"q": "How many half-value layers cut a gamma beam by about a thousand?", "a": "10", "w": ["3", "100", "1000"], "why": "2¹⁰ = 1024."}, {"q": "A shield 3 half-value layers thick. What fraction of the beam passes?", "a": "1/8", "w": ["1/3", "1/6", "1/9"], "why": "(1/2)³."}, {"q": "For high-energy gamma rays, what mostly decides how well a material shields?", "a": "the mass per area in the beam’s path", "w": ["its colour", "its electrical conductivity", "its melting point"], "why": "Thick cheap concrete can match thin dense lead."}, {"q": "A small source; you step from 2 m to 6 m away. By what is the dose rate divided?", "a": "9", "w": ["3", "6", "36"], "why": "Inverse square: (6/2)²."}, {"q": "Units for absorbed dose and for its biological harm?", "a": "grays and sieverts", "w": ["sieverts and grays", "becquerels and curies", "roentgens and joules"], "why": "Harm weighs the dose by radiation type."}, {"q": "Against galactic cosmic rays, why are hydrogen-rich materials preferred over lead?", "a": "light nuclei break the incoming nuclei with fewer secondary particles", "w": ["lead is too heavy to launch, but shields better per kilogram", "hydrogen absorbs gamma rays completely", "cosmic rays are alpha particles, stopped by paper"], "why": "Heavy metal walls make fragment showers."}];
