(window.LADDER_CARDS=window.LADDER_CARDS||{})["25·phys"]=[{"q": "Power radiated per square metre by a black body at temperature T. What is the law?", "a": "σT⁴, the Stefan-Boltzmann law", "w": ["σT², Wien’s law", "σT, Ohm’s law", "σ/T⁴, the inverse fourth law"], "why": "Stefan 1879, Boltzmann 1884."}, {"q": "A star with twice the sun’s radius and the sun’s surface temperature. What is its luminosity?", "a": "4 L⊙", "w": ["2 L⊙", "8 L⊙", "16 L⊙"], "why": "L ∝ R²."}, {"q": "A star with the sun’s radius and twice its surface temperature. What is its luminosity?", "a": "16 L⊙", "w": ["2 L⊙", "4 L⊙", "8 L⊙"], "why": "L ∝ T⁴."}, {"q": "A star with luminosity 100 L⊙ and surface temperature 2 T⊙. What is its radius?", "a": "2.5 R⊙", "w": ["40 R⊙", "5 R⊙", "25 R⊙"], "why": "R/R⊙ = √(L/L⊙) · (T⊙/T)² = 10/4."}, {"q": "A plot of stars’ luminosity against surface temperature. What is it called?", "a": "the Hertzsprung-Russell diagram", "w": ["the Hubble diagram", "the Feynman diagram", "the phase diagram"], "why": "Main sequence, giants, dwarfs."}, {"q": "With L ∝ M^3.5 and a sun lifetime of 10¹⁰ years, about how long does a 4 M⊙ main-sequence star live?", "a": "about 3 × 10⁸ years", "w": ["about 2.5 × 10⁹ years", "about 4 × 10¹⁰ years", "about 6 × 10⁸ years"], "why": "t ∝ M^(−2.5): 10¹⁰/32."}, {"q": "About what fraction of the mass is turned into energy when hydrogen fuses into helium?", "a": "0.7%", "w": ["7%", "70%", "0.007%"], "why": "Four protons outweigh a helium nucleus."}, {"q": "Pressure pushing out balancing gravity pulling in, at every depth. What is the state called?", "a": "hydrostatic equilibrium", "w": ["thermal runaway", "radiative transfer", "gravitational collapse"], "why": "kT ≈ GMm/R, from the virial theorem."}, {"q": "In a star cluster, the heaviest stars still on the main sequence. What do they mark, and what does it give?", "a": "the turnoff point; the cluster’s age", "w": ["the turnoff point; the cluster’s distance", "the instability strip; its mass", "the zero-age main sequence; its colour"], "why": "Heavier stars have already left."}, {"q": "Who showed in 1939 how hydrogen fuses into helium inside stars?", "a": "Hans Bethe", "w": ["Arthur Eddington", "Albert Einstein", "Edwin Hubble"], "why": "The proton-proton chain and the CNO cycle."}];
